def make(rid,claims,notes,**extra):
 if (O/'review/configs'/f'{rid}.json').exists():return
 g=json.loads((O/'records'/rid/'source-gold.json').read_text(encoding='utf8')); events=[]
 for needle,description,labels in claims:
  pages=[n for n in g['original_referring_instrument']['source_pages'] if needle in re.sub(r'\s+',' ',(O/'source-text'/K/f'page-{n:04}.txt').read_text(encoding='utf8'))];assert pages,(rid,needle)
  events.append(dict(source_page=pages[0],paragraphs=[],quote=needle,description=description,exhibits=labels,date=None,precision='undated',status='deponent_assertion_or_proposed_relief_not_adjudicated_finding'))
 p=O/'review/configs'/f'{rid}.json';assert not p.exists()
 p.write_text(json.dumps(dict(source_review_complete=True,source_inventory_review_notes=notes,extra_events=events,**extra),ensure_ascii=False,indent=2)+'\n',encoding='utf8')

